"""Render Markdown reports from computed results.

Every number in the generated reports is interpolated from analysis outputs;
nothing is typed in by hand. Re-run ``python scripts/run_pipeline.py`` to
regenerate them.
"""

import re
from pathlib import Path

import numpy as np
import pandas as pd

from .config import SYNTHETIC_DISCLAIMER
from .metrics import average_retention_curve

GENERATED_NOTE = "_This file is generated by `python scripts/run_pipeline.py`. Do not edit by hand; edit `src/retailpulse360/reporting.py` instead._"


def usd(value: float, decimals: int = 0) -> str:
    sign = "-" if value < 0 else ""
    value = abs(value)
    if value >= 1e6:
        return f"{sign}${value / 1e6:,.2f}M"
    if value >= 1e4:
        return f"{sign}${value / 1e3:,.1f}K"
    return f"{sign}${value:,.{decimals}f}"


def pct(value: float, decimals: int = 1) -> str:
    return f"{value:.{decimals}f}%"


def value_range(low: float, high: float, fmt: str = "{:.0f}", suffix: str = "") -> str:
    """'a–b' range text, collapsing to 'about a' when both ends round the same."""
    a, b = fmt.format(low), fmt.format(high)
    return f"about {a}{suffix}" if a == b else f"{a}–{b}{suffix}"


def markdown_table(df: pd.DataFrame, formats: dict | None = None, index: bool = False) -> str:
    """Minimal Markdown table writer (avoids an extra dependency)."""
    formats = formats or {}
    frame = df.reset_index() if index else df
    lines = ["| " + " | ".join(str(c) for c in frame.columns) + " |", "|" + "|".join("---" for _ in frame.columns) + "|"]
    for _, row in frame.iterrows():
        cells = []
        for column in frame.columns:
            value = row[column]
            if column in formats and pd.notna(value):
                cells.append(formats[column](value) if callable(formats[column]) else formats[column].format(value))
            elif isinstance(value, (float, np.floating)):
                cells.append("" if pd.isna(value) else f"{value:,.2f}")
            elif isinstance(value, pd.Timestamp):
                cells.append(f"{value:%Y-%m-%d}")
            else:
                cells.append(str(value))
        lines.append("| " + " | ".join(cells) + " |")
    return "\n".join(lines)


def update_marked_section(path: Path, marker: str, content: str) -> None:
    """Replace text between <!-- MARKER:START --> and <!-- MARKER:END --> in a file."""
    text = path.read_text(encoding="utf-8")
    pattern = re.compile(rf"(<!-- {marker}:START -->)(.*?)(<!-- {marker}:END -->)", re.DOTALL)
    if not pattern.search(text):
        raise ValueError(f"Marker {marker} not found in {path}")
    path.write_text(pattern.sub(lambda m: f"{m.group(1)}\n{content.strip()}\n{m.group(3)}", text), encoding="utf-8")


