def render_data_quality_report(audit: dict, frame: pd.DataFrame) -> str:
    overview = audit["overview"]
    pk = audit["primary_keys"]
    fk = audit["foreign_keys"]
    rules = audit["business_rules"]
    recon = audit["reconciliation"]
    repro = audit["snapshot_reproduction"]
    outliers = audit["outliers"]
    flagged = rules[rules["rows_flagged"] > 0]
    sentinel = int(frame["no_purchase_12m"].sum())
    sentinel_with_history = int(((frame["no_purchase_12m"] == 1) & (frame["never_purchased"] == 0)).sum())
    never = int(frame["never_purchased"].sum())
    no_ticket = int((frame["support_tickets_12m"] == 0).sum())
    coupon_no_discount = int(rules.loc[rules["check"].str.startswith("coupon_used = 1"), "rows_flagged"].iloc[0])

    documented = {"customers": 6000, "products": 120, "orders": 30054, "order_items": 56183, "web_sessions": 76327, "support_tickets": 4662, "marketing_spend": 174}
    overview = overview.assign(documented_rows=overview["table"].map(documented))
    overview["matches_docs"] = np.where(overview["rows"] == overview["documented_rows"], "yes", "NO")

    profiles = audit["profiles"]
    date_profile = profiles[profiles["dtype"].str.startswith("datetime")][["table", "column", "min", "max"]]

    sections = [
        "# Data Quality Report — RetailPulse 360",
        f"> **Synthetic data disclosure.** {SYNTHETIC_DISCLAIMER}",
        GENERATED_NOTE,
        "## 1. Summary",
        "\n".join(
            [
                f"- All {len(overview)} raw tables and the modeling snapshot load without errors; row counts match `docs/dataset_notes.md` for every table.",
                f"- **No missing values** in any raw table or the snapshot ({int(overview['missing_cells'].sum())} missing cells in raw tables, {audit['snapshot_missing_cells']} in the snapshot) and **no exact duplicate rows**.",
                f"- **Primary keys are unique** in all {len(pk)} tables (marketing uses the composite key `month + channel`).",
                f"- **Referential integrity holds**: {int(fk['orphan_rows'].sum())} orphan rows across {len(fk)} foreign-key relationships; every order has line items.",
                "- Order-level money fields reconcile exactly with line items under the status rules in Section 4.",
                f"- Every one of the {len(repro)} numeric snapshot features was rebuilt from raw data using only events on or before 2026-05-31, with a minimum match rate of {pct(100 * repro['match_rate'].min())}. This is strong evidence the snapshot features contain **no post-snapshot leakage**.",
                f"- Issues that need handling: (a) a **recency sentinel** in the snapshot for {sentinel:,} customers, (b) **imputed CSAT** for {no_ticket:,} customers without tickets, (c) {coupon_no_discount:,} orders flagged `coupon_used = 1` with a 0% discount, (d) **left-censored history**: customers signed up from 2023 but orders start in January 2024.",
            ]
        ),
        "## 2. Tables, row counts and date ranges",
        markdown_table(overview[["table", "rows", "documented_rows", "matches_docs", "columns", "missing_cells", "duplicate_rows", "date_range"]]),
        f"Snapshot: {audit['snapshot_rows']:,} rows, {audit['snapshot_duplicate_ids']} duplicate customer IDs, snapshot date 2026-05-31.",
        "Date columns:",
        markdown_table(date_profile, {"min": lambda v: f"{v:%Y-%m-%d}", "max": lambda v: f"{v:%Y-%m-%d}"}),
        "## 3. Keys and relationships",
        "Repeated foreign keys (e.g. a customer with many orders, or a month repeated across six channels) are legitimate and are **not** treated as duplicates. Duplicates are tested only on primary keys and on whole rows.",
        markdown_table(pk),
        markdown_table(fk),
        "Relationship map: `customers 1─* orders 1─* order_items *─1 products`; `customers 1─* web_sessions`; `customers 1─* support_tickets`. `marketing_spend` has no customer key; it joins to customers only at the aggregate level, through `channel = customers.acquisition_channel`. Support tickets have no `order_id`, so a ticket cannot be tied to a specific order.",
        "## 4. How order status affects revenue, cost and profit",
        markdown_table(recon),
        "\n".join(
            [
                "Resulting definitions (see `docs/metric_definitions.md`):",
                "- **GMV** (`gross_merchandise_value_usd`) is the *post-discount* merchandise value of every placed order, whatever its status. It excludes shipping and tax and measures demand, not earned revenue.",
                "- **Net revenue** is recognised only on Completed orders and equals GMV + shipping fee. Sales tax is excluded (it is a pass-through liability).",
                "- **Refunded orders** have zero revenue but keep their merchandise cost, so each one is a loss equal to the cost of goods. The data implies returned goods are not restocked; this is a property of the synthetic data and is treated as an assumption.",
                "- **Cancelled orders** carry zero revenue, cost and profit, even though their line items keep a cost value. Order-level fields are the source of truth.",
                "- Because of these rules, **AOV uses Completed orders only**, and the **refund rate uses fulfilled orders** (Completed + Refunded) as its denominator.",
                "- Joining orders to order_items repeats order-level values once per line. Line-level revenue must be summed from `line_revenue_usd` and order-level values from the orders table; never sum order fields after the join (fan-out).",
            ]
        ),
        "## 5. Business-rule checks",
        markdown_table(rules),
        "Interpretation of the non-zero checks:",
        "\n".join(
            [f"- **{r.table} — {r.check}: {r.rows_flagged:,} rows.** " + _rule_comment(r.check) for r in flagged.itertuples()]
        ),
        "## 6. Outliers (3 × IQR rule)",
        "Extreme values were counted, not removed. They are plausible for a retailer (large baskets, long sessions, slow tickets), and the raw data is never modified.",
        markdown_table(outliers),
        "## 7. Modeling-snapshot review (leakage and synthetic artifacts)",
        markdown_table(repro, {"match_rate": lambda v: pct(100 * v)}),
        "\n".join(
            [
                "Findings and resolutions:",
                "- **Window definitions (reverse-engineered and verified):** 12-month features use Completed orders and tickets dated from 2025-05-31 to 2026-05-31 inclusive, and 90-day web features use sessions from 2026-03-02 to 2026-05-31 inclusive. `refund_rate_12m` is refunded orders divided by *all* orders in the window (cancellations included), which differs slightly from the KPI refund rate. `cart_add_rate_90d` is cart adds per product view.",
                f"- **Recency sentinel:** for the {sentinel:,} customers with no Completed order in the 12-month window, `recency_days` is set to `days_since_signup + 30`. Of those, {sentinel_with_history:,} customers did buy earlier, so their real recency is overstated or understated by an arbitrary amount, and {never:,} never purchased at all. **Resolution:** models use `days_since_last_purchase` (true recency over all observed history) plus explicit `never_purchased` and `no_purchase_12m` flags instead of the sentinel. Notebook 02 checks how sensitive the results are to this change.",
                f"- **Imputed values:** customers without tickets have `avg_csat_12m = 4.0` and `avg_resolution_hours_12m = 0` ({no_ticket:,} customers). `support_tickets_12m = 0` identifies these rows, so models can separate the imputed value from real scores.",
                "- **Target:** `churned_next_90d` describes events after the snapshot. Raw data ends on 2026-05-31, so the label **cannot be verified** from the transactions. The project documentation states that it is synthetic and generated probabilistically from risk signals plus noise, so model scores measure how well the generator's logic is recovered, not real customer behaviour.",
                "- **Static attributes:** `loyalty_tier`, `region`, `acquisition_channel` and `preferred_device` are single current values with no history. If the tier were assigned *after* the snapshot, it would leak information. The project assumes it was known at the snapshot date, and this assumption is documented as a risk.",
                "- **Excluded from predictors:** `customer_id`, `snapshot_date` and the target. This is enforced in code by `features.assert_no_leakage`.",
            ]
        ),
        "## 8. Assumptions and limitations",
        "\n".join(
            [
                "- The data is synthetic. Distributions are cleaner and more uniform than real data. For example, funnel conversion barely varies by device or traffic source, so a lack of differences should not be read as a real-world finding.",
                "- Order history begins in January 2024, but 2023 sign-ups exist. Cohort analyses label the first *observed* purchase, so 2024 cohorts mix new and existing customers.",
                "- Profit excludes shipping, payment, support, overhead and marketing costs, none of which are in the data at order level. Marketing spend is analysed separately and only at channel and month grain.",
                "- Organic Search and Referral have recorded spend. This is assumed to cover SEO, content and referral-programme costs.",
                "- Raw CSV files are read-only inputs. No rows were removed or values altered; every correction (e.g. true recency) is a new derived column.",
            ]
        ),
    ]
    return "\n\n".join(sections) + "\n"


def _rule_comment(check: str) -> str:
    if check.startswith("coupon_used = 1"):
        return "A coupon flag without a percentage discount could mean a free-shipping or fixed-amount coupon, or a data-entry inconsistency. No coupon-type field exists, so discount analysis uses `discount_pct`, and `coupon_used` is reported as-is."
    if check.startswith("Completed order with negative profit"):
        return "Both orders carry a 25% discount, which pushed the price below unit cost. They are valid transactions and illustrate the margin risk of deep discounts."
    return "Reviewed; kept as-is."


